import{c as t,Q as n,j as s,m as r}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/settings.md","filePath":"user/reference/settings.md"}'),o={name:"user/reference/settings.md"};function a(i,e,h,d,l,g){return n(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers and operators setting up Manager on a computer.</p><p>What each page of <strong>Settings</strong> controls. Settings belong to the computer running Manager and apply to every event on it; many are only defaults that each event can change for itself in <strong>Event details</strong>.</p><h2 id="opening-settings" tabindex="-1">Opening Settings <a class="header-anchor" href="#opening-settings" aria-label="Permalink to &quot;Opening Settings&quot;">​</a></h2><p>Click the <strong>cog</strong> at the top of the <strong>Events</strong> list. The pages are listed down the left, in five groups: <strong>Global registry</strong>, <strong>Printing</strong>, <strong>Integrations and devices</strong>, <strong>System</strong> and <strong>Appearance</strong>. The top bar shows the version of the page you&#39;re using and of the server.</p><p>Most pages show <strong>Unsaved changes</strong> with <strong>Save</strong> and <strong>Discard</strong> at the bottom once you change something; nothing applies until you save. A few save as you go instead: the <strong>Club registry</strong> and <strong>Competitor registry</strong>, <strong>Printers</strong>, <strong>Live standby</strong> and <strong>This computer</strong>. <strong>Access protection</strong> has its own <strong>Set PIN</strong> button. Some settings only take effect when the server next starts, and say so: <strong>AI assistants</strong>, <strong>Allow access from other devices on the network</strong> and <strong>Enable HTTPS</strong>.</p><p><strong>Settings aren&#39;t part of an event.</strong> They stay on this computer, so a backup or an event moved to another computer doesn&#39;t take them along. See <a href="./../event-setup/moving-an-event#set-up-what-belongs-to-the-laptop">Moving an event to another computer</a>.</p><h2 id="global-registry" tabindex="-1">Global registry <a class="header-anchor" href="#global-registry" aria-label="Permalink to &quot;Global registry&quot;">​</a></h2><p>Lists that every event on this computer shares.</p><h3 id="club-registry-and-competitor-registry" tabindex="-1">Club registry and Competitor registry <a class="header-anchor" href="#club-registry-and-competitor-registry" aria-label="Permalink to &quot;Club registry and Competitor registry&quot;">​</a></h3><p>The clubs and people Manager knows, used to suggest names, clubs and card numbers as you type and at the registration desk. They can be refreshed from Eventor. See <a href="./club-registry">Club Registry</a> and <a href="./competitor-registry">Competitor Registry</a>.</p><h3 id="hire-card-registry-and-other-hire-registry" tabindex="-1">Hire card registry and Other hire registry <a class="header-anchor" href="#hire-card-registry-and-other-hire-registry" aria-label="Permalink to &quot;Hire card registry and Other hire registry&quot;">​</a></h3><p>The pool of hire-card numbers your club lends out, each with an optional <strong>Owner</strong>, and the other things you lend: compasses, map boards. Shared by every event on this computer.</p><ul><li><strong>Hire card registry</strong> — type card numbers into <strong>Quick add card numbers</strong> (commas or spaces, and ranges such as <code>1001-1010</code>), or use <strong>Range from</strong> / <strong>Range to</strong> and <strong>Add range</strong>. With a SportIdent reader connected you can instead read each card on it to add it; <strong>Connect card reader</strong> appears here when none is connected (it is the same reader card download uses). Tick cards in the list to <strong>Set owner</strong>, <strong>Clear owner</strong> or <strong>Remove selected</strong>, or use <strong>Clear all</strong>. Click <strong>Save</strong> when you&#39;re done.</li><li><strong>Other hire registry</strong> — <strong>Add item</strong>, give it an <strong>Item name</strong> and optional owner, and either say <strong>How many you have</strong> (0 if you don&#39;t count them) or turn on <strong>Individually numbered</strong> and list its <strong>Item numbers</strong> (ranges such as <code>1-30</code> are expanded).</li></ul><p>See <a href="./../running-the-event/hire-items">Hire items</a>.</p><h3 id="custom-fields" tabindex="-1">Custom fields <a class="header-anchor" href="#custom-fields" aria-label="Permalink to &quot;Custom fields&quot;">​</a></h3><p>Extra fields recorded against every competitor, beyond the built-in ones. Shared across all events, so the same set is there for every event you run.</p><ul><li>Each field has a name of your choosing and holds either <strong>text</strong> or a <strong>number</strong>. The type decides how the value sorts in a column: a Number field sorts numerically, so 9 comes before 10 rather than after it. Values are always stored as text either way, and a value that can&#39;t be read as a number sorts last.</li><li>Use <strong>Move up</strong> / <strong>Move down</strong> to set the order fields appear in, everywhere they are shown.</li><li><strong>Renaming a field keeps the values competitors already hold.</strong> Removing one hides it without deleting those values, so adding the field back <em>under the same name</em> brings them with it — under different wording it is a new, empty field.</li><li>Fields appear on the <strong>Custom fields</strong> tab of a competitor, on a <strong>Competitor registry</strong> entry, and as optional columns in the Competitors list and the Competitor registry table. In the Competitors list they are off by default (turn them on from the Columns menu); in the registry table they are shown by default.</li><li>Values recorded on a <strong>Competitor registry</strong> entry follow that person into every event they enter: they are copied onto the competitor when you import entries from Eventor or from an IOF XML entry list, and when you pick the person from the registry in the Edit Competitor dialog. A value already on the competitor always wins, so re-importing an entry list never overwrites a correction you made in the event — it only fills in fields that are still blank.</li><li>For an IOF XML file, the link relies on the file carrying the athlete&#39;s <strong>IOF ID</strong>. Entry lists exported by Eventor normally do; a file without it cannot be tied to a registry person, so those competitors arrive with the fields blank. Card number and name are deliberately not used for the match, because hire cards change hands.</li><li>Custom fields go into the <strong>CSV</strong> entry-list export and into <a href="./../advanced/orienteering-json">Orienteering JSON</a> files, and the CSV entry import reads them back (a column is matched to a field by its name). They are <strong>not</strong> in IOF XML, which has nowhere to put them, nor on results or splits printouts.</li><li>If you have enabled <a href="./ai-assistants-mcp">AI assistants (MCP)</a>, custom fields are among the competitor details an assistant can read. Bear that in mind for anything sensitive, such as a phone number.</li></ul><h2 id="printing" tabindex="-1">Printing <a class="header-anchor" href="#printing" aria-label="Permalink to &quot;Printing&quot;">​</a></h2><p>Every printer, and what is printed on it. The full guide is <a href="./../running-the-event/splits-printing">Printing splits</a>.</p><ul><li><strong>Printers</strong> — every printer Manager can print on, and every computer it is open on, drawn as a live map and then listed: printers on the network, printers plugged into the server&#39;s computer (through Windows, or the print system of a Mac or Linux computer), and USB printers plugged into a laptop running Manager. Each printer has a name (where it stands — <em>Lane A</em>, <em>Results board</em>), its own paper width (except a printer drawn for its driver in Windows, whose paper size Windows sets), and either its characters per line and paper cut (a thermal printer) or its text size, boldness and line spacing (a printer drawn for its driver). <strong>Add a printer</strong> starts by asking where it is plugged in. A laptop&#39;s USB printer is <strong>shared</strong> with every computer to begin with, while Manager is open on that laptop. <strong>This computer</strong> shows the printer plugged into the computer you are at and where its splits and labels print; <strong>Set up here before?</strong> lets a laptop opened at a new web address pick up the setup it had. Nothing on this page waits for the Settings <strong>Save</strong> button: a printer is saved from its own dialog, and a computer&#39;s choices apply as you make them.</li><li><strong>Splits print</strong> — the <strong>Default splits printer</strong> (or <strong>Not printed</strong>; it must be a printer every computer may use), where each computer&#39;s splits print, and then when a slip prints and what is on it: auto-print on download, whether a mis-punch printout is held while you correct the class and for how long, logo, top 3 places, the mistakes and strong legs sections, splits language, and the QR code. Each event can override when and what in <strong>Event details → Printing</strong>.</li><li><strong>Result labels</strong> — a small printout per competitor for the results board, independent of the splits, and laid out as the splits print is. <strong>Where</strong>: the label printer (Not printed, the splits printer straight after the splits, or a printer of its own; like the default splits printer, one every computer may use) and where each computer&#39;s labels print. <strong>When</strong>: its own switch (off to begin with) and its own mis-punch hold. <strong>Layout</strong>: three rows with a place at the left, centre and right of each, set separately for <strong>Individual</strong> and <strong>Relays</strong> (<strong>Layout for</strong>), the <strong>Space above the label</strong> and <strong>Space below the label</strong>, a preview and <strong>Test print</strong>.</li><li>Upgrading from a version before printers and computers: see <a href="./../running-the-event/splits-printing#what-an-upgrade-does-to-printing">What an upgrade does to printing</a>.</li><li><strong>Radio downloads</strong> — whether a card read by a radio download station and sent over the meshO network prints its splits and label, and where, since no computer read it. Each event can override these.</li></ul><h2 id="integrations-and-devices" tabindex="-1">Integrations and devices <a class="header-anchor" href="#integrations-and-devices" aria-label="Permalink to &quot;Integrations and devices&quot;">​</a></h2><h3 id="eventor" tabindex="-1">Eventor <a class="header-anchor" href="#eventor" aria-label="Permalink to &quot;Eventor&quot;">​</a></h3><p>Connects Manager to Eventor, to create events from it, import entries and start times, refresh the registries, and upload start lists and results.</p><ul><li><strong>Enable Eventor</strong>, then your <strong>Host name</strong>, <strong>API key</strong> and <strong>Organisation ID</strong> (your organisation&#39;s number in Eventor, which scopes the events shown and the competitors and clubs fetched; use 1 to fetch all competitors and clubs).</li><li><strong>Event history</strong> — how far back the import picker lists events: <strong>Future only</strong> (the default, and quickest), <strong>Include past week</strong>, <strong>Include past month</strong> or <strong>Include past 6 months</strong>. Each extra month of history is another request to Eventor.</li><li><strong>Events list</strong> — <strong>Show upcoming Eventor events on the events list</strong> offers them beside your own, so you can create an event from one with a click. Choose <strong>Organisations</strong> (an association brings in its clubs&#39; events too; save the host and API key first so the list can be fetched), enter text for <strong>Event name contains</strong>, or both. With neither, no Eventor events are shown.</li></ul><p>See <a href="./../event-setup/create-event-from-eventor">Creating an event from Eventor</a>.</p><h3 id="cloud-sync" tabindex="-1">Cloud sync <a class="header-anchor" href="#cloud-sync" aria-label="Permalink to &quot;Cloud sync&quot;">​</a></h3><p>Publishes events to the meshO cloud (events.mesho.live), where spectators can browse their results online. It is set up out of the box: the <strong>Cloud URL</strong> points at the meshO cloud, and the <strong>Push token</strong> field is left blank because Manager carries its own token for that server.</p><ul><li><strong>Publish events to the cloud automatically when they are finished</strong> is on to begin with. When you finish an event (or use <strong>Mark finished</strong>), it is queued and uploaded in the background — you do not wait for it, and nothing about finishing changes.</li><li><strong>No internet at the venue is fine.</strong> The queue is kept with the event on disk, so you can finish, close the laptop and drive home: the event goes up the next time this computer is online, including after a restart. While an event is live nothing is uploaded, so the upload never competes with radio punches or live results for the venue&#39;s connection.</li><li>Each event card shows where it stands with a small grey cloud beside the status chip: a tick once it is on the cloud (hover for when), a clock while it is waiting. A cloud with an exclamation mark, in the warning colour, means something waiting will not fix — a refused token, or an event larger than the cloud accepts — and hovering says which.</li><li>Turning automatic sync <strong>off</strong> stops new events being queued and also pauses any that are already waiting, so it is the way to stop an upload that has not happened yet. You can still publish any event by hand with its <strong>Push to cloud</strong> action.</li><li><strong>Test connection</strong> checks the server at <strong>Cloud URL</strong> answers and is a cloud server; save your changes first.</li><li>Running your own cloud server? Put its address in <strong>Cloud URL</strong> and its token in <strong>Push token</strong>. Manager&#39;s own token is only ever sent to the meshO cloud, never to another server. Clearing the <strong>Cloud URL</strong> turns cloud sync off altogether.</li><li>What gets published is the whole event — competitors&#39; names, clubs and results — on a public site. If an event should not be public (a training run, a private club event), turn its automatic sync off before you finish it: each event can decide for itself in <strong>Event details → Cloud sync</strong>, whatever this setting says. Some events are never published automatically: one finished before its own date (a rehearsal or a test), one run in test mode, one with fewer than five results (a finish, a mispunch, a retirement or a disqualification each count; runners with no status, still out or not starting do not), and a sample event, which starts with its automatic sync off. You can still publish any of them with <strong>Push to cloud</strong>.</li><li><strong>Event details → Cloud sync</strong> also lists every time the event has been synced (when, whether it was published, updated or deleted, whether that was automatic or by hand, and how much was uploaded), links to its page on the cloud, and has <strong>Delete from the cloud</strong>, which takes it off the public site. The event on your computer is not touched, and its automatic sync is switched off, so finishing it again does not put it back.</li><li>For what a cloud copy shows and hides, and how it compares with liveresultat, see <a href="./../running-the-event/publishing-live-results#publishing-to-the-mesho-cloud">Publishing live results online</a>.</li></ul><h3 id="live-standby" tabindex="-1">Live standby <a class="header-anchor" href="#live-standby" aria-label="Permalink to &quot;Live standby&quot;">​</a></h3><p>Lets a second meshO Manager on the network keep a live copy of every event in progress, ready to take over if this computer fails: the switch that allows it, this computer&#39;s address and pairing code to type on the standby, what else the standby copies (settings and PIN, the HTTPS certificate, printers and computers, the registries), and which standbys are following now. See <a href="./../running-the-event/live-standby">Live standby</a>.</p><h3 id="radio-punches" tabindex="-1">Radio punches <a class="header-anchor" href="#radio-punches" aria-label="Permalink to &quot;Radio punches&quot;">​</a></h3><p>meshO Prime and the radio-punch connections, on one page:</p><ul><li><strong>meshO Prime</strong> — <strong>Use meshO Prime for radio punches</strong>: the default for new events. Each event can change it on <strong>Event details → Radio controls</strong>. See <a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a>.</li><li><strong>Radio punch forwarding</strong> — sends radio punches on to other timing software over TCP: <strong>TCP host</strong>, <strong>TCP port</strong> (10000 to begin with), <strong>Protocol</strong> (SIRAP, the default, or OE12) and <strong>Client name</strong>, with <strong>Test connection</strong>.</li><li><strong>Radio punch listening</strong> — accepts SIRAP punches from another system on a <strong>Listen port</strong> (10000 to begin with).</li></ul><p>See <a href="./../running-the-event/radio-punches#forwarding-and-receiving-punches">Forwarding and receiving punches</a>.</p><h3 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h3><p>What this server does with the pictures a camera sends it (cameras themselves are set up on the device holding them, at <strong>/info → Camera</strong> — see <a href="./../screens/info-screens">Info screens</a>). A change applies to the next camera that starts sending; one already sending keeps what it started with.</p><table tabindex="0"><thead><tr><th>Setting</th><th>To begin with</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Record cameras by default</strong></td><td>On</td><td>Whether a camera records as well as showing a live picture, unless whoever sets it up turns that off for theirs.</td></tr><tr><td><strong>Keep recordings for (days)</strong></td><td>30</td><td>How long a recording is held before Manager tidies it away. 0 keeps them until you delete them yourself.</td></tr><tr><td><strong>Minutes per recording file</strong></td><td>10</td><td>How much each file covers.</td></tr><tr><td><strong>Picture quality (kbit/s)</strong></td><td>1500</td><td>What a camera is <em>asked</em> to encode at, with the resulting MB per hour shown beside it.</td></tr><tr><td><strong>Stop recording below (MB free)</strong></td><td>2048</td><td>The disk floor recording gives way at, so a full disk can&#39;t take the event down with it. The live picture keeps working.</td></tr><tr><td><strong>Ride out a dropped connection for (seconds)</strong></td><td>120</td><td>How long a camera holds pictures it can&#39;t send, and how long its recording waits for it. 0 turns it off.</td></tr></tbody></table><p>Each field accepts values within a set range, and a value outside it is brought back inside. Recordings are kept on this server only, <strong>outside</strong> the event folder, so they are in no event backup and no cloud sync; they are tidied away some time after their event is deleted.</p><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2><h3 id="event-defaults" tabindex="-1">Event defaults <a class="header-anchor" href="#event-defaults" aria-label="Permalink to &quot;Event defaults&quot;">​</a></h3><p>Defaults for events. Most are copied into a new event when it&#39;s created, so changing them later doesn&#39;t change events you already have; each event changes its own in <strong>Event details</strong>. The page has four parts:</p><ul><li><strong>Starts</strong><ul><li><strong>Punching starts override allocated starts</strong> — whether a start-unit punch replaces an allocated start time, for a new event. See <a href="./../event-setup/start-times#punched-starts">Punched starts</a>.</li><li><strong>Time runners with no start from check punch or midnight</strong> — on to begin with. Unlike the others, this one isn&#39;t copied: every event follows it unless it has chosen otherwise on its <strong>Starts</strong> tab, so changing it re-scores any running event that follows it. See <a href="./status-and-race-time#a-runner-with-no-start-time">A runner with no start time</a>.</li></ul></li><li><strong>Timing system</strong> — <strong>Timing card system</strong>: SportIdent or EMIT, for a new event. An event can change it during setup.</li><li><strong>Replay mode</strong> — <strong>Default replay speed</strong> (0.5x to 100x), for replaying a captured event, a testing and training tool.</li><li><strong>Leaderboard screen defaults</strong> — how a new leaderboard screen starts: <strong>Club display</strong> (Hide, Full names or Abbreviations), <strong>Show club logo</strong>, <strong>Max radios per class</strong> and <strong>Competitor time display</strong> (Elapsed, Difference or Both). Each screen changes its own. See <a href="./../screens/creating-screens">Creating screens</a>.</li><li><strong>Start/finish/check radio control codes</strong> — <strong>Start codes</strong>, <strong>Finish codes</strong> and <strong>Check codes</strong>: the codes your start, finish and check units punch as, comma-separated, for a new event. A radio punch carries only a code, so these are how Manager tells a start or finish from a control on the course. A code can&#39;t be in more than one box. See <a href="./../event-setup/controls-and-radio-controls#start-finish-and-check-codes">Start, Finish and Check codes</a>. To use one of the course&#39;s numbered controls as its start or finish instead, see <a href="./../event-setup/classes-and-courses#starting-or-finishing-at-a-numbered-control">Starting or finishing at a numbered control</a>.</li></ul><p>Whether an event is timed to fractions of a second isn&#39;t a default: each event decides it with <strong>Use sub-second timing</strong> in its own <strong>Event details</strong>. See <a href="./status-and-race-time#timing-to-the-second-or-to-fractions-of-a-second">Timing to the second or to fractions of a second</a>.</p><h3 id="server" tabindex="-1">Server <a class="header-anchor" href="#server" aria-label="Permalink to &quot;Server&quot;">​</a></h3><ul><li><strong>This computer&#39;s name</strong> and <strong>LAN IP</strong>, and how to rename the computer for a friendlier address.</li><li><strong>HTTP port</strong> — 5154 to begin with.</li><li><strong>Allow access from other devices on the network</strong> — on to begin with. Off, only this computer can open Manager. Takes effect the next time the server starts.</li><li><strong>Access links</strong> — the links to give every other device: Manager, Registration, Spectator, Kiosk, Info screens and Commentary, each by name and by IP (and over HTTPS too once that&#39;s on), with a copy button and <strong>Show QR code</strong> to open one on a phone. See <a href="./server-addresses">Reaching the server: name or IP</a>.</li><li><strong>Enable HTTPS (for download / station-backup machines)</strong> — off to begin with. Laptops other than the server need a secure link to use a card reader. Once it&#39;s on: <strong>HTTPS port</strong> (5155 to begin with), <strong>Install certificate on the server</strong>, and the certificate to download for other devices. Takes effect the next time the server starts. See <a href="./https-and-certificates">HTTPS and certificates</a>.</li></ul><h3 id="access-protection" tabindex="-1">Access protection <a class="header-anchor" href="#access-protection" aria-label="Permalink to &quot;Access protection&quot;">​</a></h3><p>Sets a <strong>PIN</strong> that has to be entered before any manager screen, including the Events list, event editing and Settings, can be opened; the <a href="./../running-the-event/registration-desk">registration desk</a> asks for it too. The arena screens, the spectator site and the kiosk stay public; the commentary screen and the info screens that show results ask for it only while a class is in a <a href="./../event-setup/results-quarantine">results quarantine</a>. Set one whenever the event&#39;s network is shared with people who shouldn&#39;t be editing it.</p><p>Type the PIN twice (at least 4 characters) and click <strong>Set PIN</strong>; afterwards the same place offers <strong>Change PIN</strong> and <strong>Remove PIN</strong>, which asks for the current PIN first. A forgotten PIN can be cleared from the tray or menu bar on the server computer: <strong>Reset Access Protection PIN</strong>.</p><h3 id="auto-update" tabindex="-1">Auto update <a class="header-anchor" href="#auto-update" aria-label="Permalink to &quot;Auto update&quot;">​</a></h3><p><strong>Automatically install updates</strong> downloads and installs new versions as they come out, and restarts the server. <strong>Check for updates</strong> checks now, and offers <strong>Update now</strong> when a newer version is out. Update notices are hidden while an event is live. See <a href="./../download-and-install/#updating">Updating</a>.</p><h3 id="ai-assistants" tabindex="-1">AI assistants <a class="header-anchor" href="#ai-assistants" aria-label="Permalink to &quot;AI assistants&quot;">​</a></h3><p>Both ways of using AI with meshO Manager, on one page:</p><ul><li><strong>The built-in assistant</strong> adds an <strong>Ask</strong> button to every event, which answers questions about using meshO Manager and, if you allow it, about the open event. To begin with it answers only questions about using meshO Manager; takes effect straight away. Needs an internet connection. See <a href="./built-in-assistant">Built-in assistant</a>.</li><li><strong>Connect your own assistant (MCP)</strong> lets an assistant you run, such as the Claude desktop app, read the live event: <strong>Allow AI assistants to connect</strong>, which shows the <strong>Address for your assistant</strong> to copy, and <strong>Let your own assistant make changes</strong>. Both are off to begin with, and both need a server restart. See <a href="./ai-assistants-mcp">AI assistants (MCP)</a>.</li></ul><h3 id="logging" tabindex="-1">Logging <a class="header-anchor" href="#logging" aria-label="Permalink to &quot;Logging&quot;">​</a></h3><p><strong>Log level</strong>: how much detail Manager writes to its log file — Verbose, Debug, Info, Warning (the default) or Error. Every event&#39;s audit trail is always recorded, whatever this says. Leave it alone unless support asks. See <a href="./troubleshooting#where-the-logs-are">Where the logs are</a>.</p><h3 id="auto-backup" tabindex="-1">Auto backup <a class="header-anchor" href="#auto-backup" aria-label="Permalink to &quot;Auto backup&quot;">​</a></h3><p>The defaults for automatic backups while an event is running: <strong>Auto backup enabled</strong> (off to begin with), how often (5, 10, 15, 30 or 60 minutes; 15 to begin with), and how many to keep per event (1, 2, 5, 10 or All; 5 to begin with). Backups go into an <code>auto-backup</code> folder inside the event&#39;s folder. Each new event starts with these, and changes its own on <strong>Event details → Backup &amp; export</strong>. See <a href="./backup-and-restore#auto-backup">Backup and restore</a>.</p><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h2><h3 id="this-computer" tabindex="-1">This computer <a class="header-anchor" href="#this-computer" aria-label="Permalink to &quot;This computer&quot;">​</a></h3><p>Settings for the browser you&#39;re using, saved on this computer only, plus the default language and the other screens&#39; themes, which apply to everyone:</p><ul><li><strong>Computer name</strong> — shown in the audit trail against every change made here. Leave it empty and the computer is listed by its network address instead. See <a href="./audit-trail#naming-a-computer">Naming a computer</a>.</li><li><strong>Default language</strong> — the language every computer and screen starts in. Applies to everyone.</li><li><strong>Language on this computer</strong> — overrides the default for this browser only; <strong>Use the default</strong> follows it.</li><li><strong>Interface scale</strong> — how large Manager draws on this screen. <strong>Automatic (fit to screen)</strong> says what it has chosen.</li><li><strong>Theme</strong> — <strong>Follow the device</strong>, <strong>Light</strong> or <strong>Dark</strong> for <strong>Manager</strong> on this computer only.</li><li><strong>Other screens</strong> — the same choice for <strong>Registration</strong>, <strong>Commentary</strong>, <strong>Kiosk</strong> and <strong>Spectator</strong>. These screens have no settings page of their own, so their theme is set here and applies to everyone connecting to this Manager. An arena screen&#39;s theme is set on that screen instead (see <a href="./../screens/creating-screens">Creating screens</a>), and the info screens each keep their own.</li></ul><h2 id="where-settings-are-kept" tabindex="-1">Where settings are kept <a class="header-anchor" href="#where-settings-are-kept" aria-label="Permalink to &quot;Where settings are kept&quot;">​</a></h2><p>Everything on these pages except <strong>This computer</strong> is stored in Manager&#39;s app-data folder on the server computer:</p><table tabindex="0"><thead><tr><th>Computer</th><th>Folder</th></tr></thead><tbody><tr><td>Windows</td><td><code>%LOCALAPPDATA%\\meshO Manager</code></td></tr><tr><td>macOS</td><td><code>~/Library/Application Support/meshO Manager</code></td></tr><tr><td>Linux</td><td><code>~/.local/share/meshO Manager</code></td></tr></tbody></table><p>In that folder:</p><table tabindex="0"><thead><tr><th>What</th><th>File</th></tr></thead><tbody><tr><td>Every page that has a <strong>Save</strong> button — including the hire registries and custom fields — and the PIN (kept only in scrambled form, never as the PIN itself), the default language and the other screens&#39; themes</td><td><code>meshO Manager.yaml</code></td></tr><tr><td>Club registry and Competitor registry</td><td><code>Clubs.json</code> and <code>Competitors.json</code></td></tr><tr><td>Printers and computers</td><td><code>Printers.json</code> and <code>Computers.json</code></td></tr><tr><td>Live standby</td><td><code>LiveStandby.json</code></td></tr><tr><td>The HTTPS certificate</td><td>the <code>certs</code> folder</td></tr><tr><td>The log files</td><td>the <code>logs</code> folder</td></tr><tr><td>Video recordings</td><td>the <code>Video</code> folder</td></tr></tbody></table><p><strong>This computer</strong>&#39;s own settings — its name, language, interface scale and Manager theme — are kept by the browser, so they belong to that browser on that computer and not to the server, and clearing the browser&#39;s site data loses them.</p><p>Change settings in <strong>Settings</strong> rather than in the file. Manager checks what it is given there, and it can overwrite a hand-edited file while it&#39;s running. Events are kept separately; see <a href="./backup-and-restore#where-backups-are-kept">Where backups are kept</a>.</p><p>There&#39;s no button to put every setting back to how it started.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../download-and-install/">Download, install and update</a></li><li><a href="./../running-the-event/splits-printing">Printing splits</a></li><li><a href="./built-in-assistant">Built-in assistant</a></li><li><a href="./ai-assistants-mcp">AI assistants (MCP)</a></li><li><a href="./https-and-certificates">HTTPS and certificates</a></li><li><a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a></li><li><a href="./../event-setup/moving-an-event">Moving an event to another computer</a></li><li><a href="./../running-the-event/live-standby">Live standby</a></li><li><a href="./../running-the-event/publishing-live-results">Publishing live results online</a></li><li><a href="./multi-operator-setup">Multi-operator setup</a> — what the access PIN protects</li></ul>',72)])])}const p=t(o,[["render",a]]);export{u as __pageData,p as default};
